import os
import json
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def extract_invoice_fields(invoice_bytes: bytes, mime_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Amazon Textract AnalyzeExpense.
    Returns a normalized dictionary.
    """
    textract = boto3.client("textract")

    try:
        response = textract.analyze_expense(
            Document={"Bytes": invoice_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {e}") from e

    expenses = response.get("ExpenseDocuments", [])
    if not expenses:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
            "raw": response,
        }

    def _get_summary_field(fields: List[Dict[str, Any]], field_type: str) -> Optional[str]:
        for f in fields:
            if f.get("Type", {}).get("Text", "").upper() == field_type.upper():
                return f.get("ValueDetection", {}).get("Text")
        return None

    def _get_summary_field_conf(fields: List[Dict[str, Any]], field_type: str) -> Optional[float]:
        for f in fields:
            if f.get("Type", {}).get("Text", "").upper() == field_type.upper():
                conf = f.get("ValueDetection", {}).get("Confidence")
                return float(conf) if conf is not None else None
        return None

    summary_fields = expenses[0].get("SummaryFields", [])
    line_item_groups = expenses[0].get("LineItemGroups", [])

    vendor = (
        _get_summary_field(summary_fields, "VENDOR_NAME")
        or _get_summary_field(summary_fields, "SELLER_NAME")
        or _get_summary_field(summary_fields, "SUPPLIER_NAME")
        or _get_summary_field(summary_fields, "RECEIVER_NAME")
    )
    date = (
        _get_summary_field(summary_fields, "INVOICE_RECEIPT_DATE")
        or _get_summary_field(summary_fields, "DATE")
    )
    total = (
        _get_summary_field(summary_fields, "TOTAL")
        or _get_summary_field(summary_fields, "AMOUNT_DUE")
        or _get_summary_field(summary_fields, "INVOICE_RECEIPT_TOTAL")
    )

    line_items: List[Dict[str, Any]] = []
    for group in line_item_groups:
        for item in group.get("LineItems", []):
            item_dict: Dict[str, Any] = {}
            for exp_field in item.get("LineItemExpenseFields", []):
                key = exp_field.get("Type", {}).get("Text") or exp_field.get("LabelDetection", {}).get("Text")
                value = exp_field.get("ValueDetection", {}).get("Text")
                if key:
                    item_dict[key.lower()] = value
            if item_dict:
                line_items.append(item_dict)

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": response,
    }


def extract_invoice_fields_from_file(file_path: str, mime_type: str = "application/pdf") -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        return extract_invoice_fields(f.read(), mime_type=mime_type)
